  "phoneAudio.title": "ஃபோன் ஆடியோ",
  "phoneAudio.hint": "இந்த ஃபோனின் இசை, வீடியோக்கள், பாட்காஸ்ட்கள் ஆகியவற்றை இந்தக் கணினியின் ஸ்பீக்கர்கள் அல்லது ஹெட்ஃபோன்களில் இயக்குங்கள். ஃபோன் முதலில் கேட்கும், பிறகு Android ஒவ்வொரு முறையும் கேட்கும். அழைப்புகள் ஒருபோதும் அனுப்பப்படாது. பதிவுசெய்ய அனுமதிக்காத ஆப்ஸ் இங்கே ஒலிக்காது.",
