  "computerAudio.title": "இந்தக் கணினியின் ஒலி",
  "computerAudio.hint": "இந்தக் கணினியை ஃபோனிலும் அதில் இணைந்த இயர்பட்களிலும் கேளுங்கள்: அது இயக்கும் அனைத்தும், உங்கள் சொந்த இணைப்பின் வழியாக. ஃபோன் முதல் முறை அனுமதி கேட்கலாம். ஒவ்வொரு முறை தொடங்கும்போதும் இந்தக் கணினி அதைத் தெரிவிக்கும்.",
  "computerAudio.hintMac": "திரையையும் சிஸ்டம் ஆடியோவையும் பதிவுசெய்ய my-domain-ஐ அனுமதிக்குமாறு macOS ஒருமுறை கேட்கும்: ஒலி மட்டுமே அனுப்பப்படும்.",
  "computerAudio.start": "{name} இல் இயக்கு",
  "computerAudio.asked": "தொடங்க {name} இல் ‘இயக்கு’ என்பதைத் தட்டுங்கள். அங்கே தட்டாமல் தொடங்காது.",
  "computerAudio.playing": "இந்தக் கணினியின் ஒலி {name} இல் இயங்குகிறது.",
  "computerAudio.cancel": "ரத்துசெய்",
  "computerAudio.stop": "நிறுத்து",
  "computerAudio.unsupported": "இந்தக் கணினியின் ஒலியைப் பகிர macOS 13 அல்லது அதற்குப் பிந்தையது, Linux அல்லது Windows தேவை.",
  "computerAudio.badge": "{names} இல் ஒலி",
  "computerAudio.badgeStop": "இந்தக் கணினியின் ஒலியை ஃபோனில் இயக்குவதை நிறுத்து",
  "phoneScreen.title": "ஃபோன் திரை",
  "phoneScreen.hint": "ஃபோனின் திரையில் என்ன உள்ளது என்பதை இங்கே பாருங்கள். ஃபோன் ஒவ்வொரு முறையும் Android இன் சொந்த அறிவுறுத்தலுடன் முதலில் கேட்கும், நிறுத்தும் வரை நீங்கள் பார்ப்பதைக் காட்டும். எதுவும் சேமிக்கப்படாது.",
  "phoneScreen.ask": "அதன் திரையைப் பார்க்கக் கேள்",
  "phoneScreen.waiting": "ஃபோனுக்காகக் காத்திருக்கிறது… முதலில் அதில் சரி என்று சொல்லுங்கள் (Android ஒவ்வொரு முறையும் கேட்கும்).",
  "phoneScreen.full": "முழுத்திரை",
  "phoneScreen.exitFull": "முழுத்திரையிலிருந்து வெளியேறு",
  "phoneScreen.stopped": "{name} தன் திரையைப் பகிர்வதை நிறுத்தியது",
  "phoneScreen.offered": "{name} தன் திரையை இந்தக் கணினியுடன் பகிர்கிறது",
  "phoneScreen.control": "கட்டுப்படுத்து",
  "phoneScreen.controlOff": "பார்வை மட்டும். படத்தில் தட்டவும் ஸ்வைப் செய்யவும் ‘கட்டுப்படுத்து’ என்பதை இயக்குங்கள்.",
  "phoneScreen.controlOn": "தட்ட கிளிக் செய்யுங்கள், நீண்ட நேரம் அழுத்தப் பிடித்திருங்கள், ஸ்வைப் செய்ய இழுங்கள்.",
  "phoneScreen.controlNeedsHelper": "இங்கிருந்து ஃபோனைக் கட்டுப்படுத்த, ஃபோனில் my-domain உதவியாளரை இயக்குங்கள் (அமைப்புகள் > அணுகல்தன்மை).",
  "phoneScreen.controlNeedsAllow": "இங்கிருந்து ஃபோனைக் கட்டுப்படுத்த, அதன் பகிர்வு அறிவிப்பில் “கட்டுப்பாட்டை அனுமதி” என்பதைத் தட்டுங்கள்.",
  "phoneScreen.back": "பின்செல்",
  "phoneScreen.home": "முகப்பு",
  "phoneScreen.recents": "சமீபத்திய ஆப்ஸ்",
  "camera.title": "ஃபோன் கேமரா",
  "camera.hint": "ஃபோனின் கேமரா பார்ப்பதைப் பாருங்கள்: அறையின் மறுபுறம் உள்ள ஒன்றையோ, மேசையில் உள்ள ஒரு பக்கத்தையோ. ஃபோன் ஒவ்வொரு முறையும் முதலில் கேட்கும், நிறுத்தும் வரை கேமரா இயக்கத்தில் இருப்பதைக் காட்டும். நீங்கள் படம் எடுத்தால் தவிர எதுவும் சேமிக்கப்படாது.",
  "camera.ask": "அதன் கேமராவைப் பார்க்கக் கேள்",
  "camera.waiting": "{name} க்காகக் காத்திருக்கிறது… ஃபோனில் ‘அனுமதி’ என்பதைத் தட்டுங்கள்.",
  "camera.starting": "கேமராவைத் தொடங்குகிறது…",
  "camera.useFront": "முன் கேமராவைப் பயன்படுத்து",
  "camera.useBack": "பின் கேமராவைப் பயன்படுத்து",
  "camera.torchOn": "டார்ச் ஆன்",
  "camera.torchOff": "டார்ச் ஆஃப்",
  "camera.photo": "படம் எடு",
  "camera.taking": "{name} இல் படம் எடுக்கிறது…",
  "camera.photoSaved": "{device} இலிருந்து வந்த படம் Downloads இல் சேமிக்கப்பட்டது",
  "camera.declined": "{name} தன் கேமராவைக் காட்ட மறுத்தது",
  "camera.stopped": "{name} தன் கேமராவை அணைத்தது",
  "camera.locked": "{name} பூட்டப்பட்டதால், அதன் கேமரா நின்றது",
  "camera.noPermission": "{name} க்குக் கேமரா அனுமதி தேவை: ஃபோனில் அனுமதித்து, பிறகு மீண்டும் கேளுங்கள்",
  "camera.busy": "{name} இன் கேமரா வேறொரு ஆப்பில் பயன்பாட்டில் உள்ளது",
  "camera.error": "{name} தன் கேமராவைத் தொடங்க முடியவில்லை",
  "a11y.cameraView": "{name} இன் கேமரா பார்ப்பது",

  // Insert from phone (InsertTile, InsertSetting)
  "insert.title": "ஃபோனிலிருந்து செருகு",
  "insert.hint": "{device} மூலம் படம் எடுங்கள் அல்லது ஆவணங்களை ஸ்கேன் செய்யுங்கள்: அது இங்கே Downloads இலும் கிளிப்போர்டிலும் வந்து சேரும். ஃபோனில் நீங்கள் தட்டும்போது மட்டுமே கேமரா திறக்கும்.",
