  "insert.photoSaved": "{device} இலிருந்து வந்த படம் சேமிக்கப்பட்டு நகலெடுக்கப்பட்டது",
  "insert.scanSaved": "{device} இலிருந்து வந்த ஸ்கேன் சேமிக்கப்பட்டு நகலெடுக்கப்பட்டது",
