  "insert.error": "{device} இல் ஏதோ தவறாகிவிட்டது",
  "insert.cancelled": "{device} இல் ரத்துசெய்யப்பட்டது",
  "insert.settingsTitle": "ஃபோனிலிருந்து செருகு",
  "insert.settingsHint": "உங்கள் ஃபோனிலிருந்து வரும் படம் அல்லது ஸ்கேன் Downloads க்கும் கிளிப்போர்டுக்கும் செல்லும். நீங்கள் பயன்படுத்தும் ஆப்பில் இதை ஒட்டவும் முடியும்.",
  "insert.pasteSwitch": "நான் இருக்கும் இடத்தில் செருகு (முன்னால் உள்ள ஆப்பில் ஒட்டு)",
  "insert.pasteNeedsAccessibility": "உங்களுக்காக ஒட்ட, System Settings › Privacy & Security › Accessibility இல் my-domain-ஐ அனுமதியுங்கள்.",
  "insert.pasteNoDisplay": "ஒட்டுவதற்கு இங்கே X11 அமர்வு தேவை.",

  // A phone's photos (PhotosTile)
  "photos.title": "படங்கள்",
  "photos.hint": "ஃபோனின் சமீபத்திய படங்களும் வீடியோக்களும், புதியவை முதலில். தேர்ந்தெடுக்கக் கிளிக் செய்து, பிறகு பதிவிறக்குங்கள்.",
