  // Scheduled actions (ScheduleTile)
  "schedule.title": "அட்டவணைகள்",
  "schedule.hint": "குறிப்பிட்ட நேரத்தில் இந்தச் சாதனத்தில் ஏதாவது செய்யுங்கள். இங்கே my-domain திறந்திருக்கும்போது இயங்கும்; இந்தக் கணினி உறக்கத்தில் அல்லது அணைந்திருக்கும்போது தவறிய நேரம் தவிர்க்கப்படும்.",
