  // This computer's own schedules (Settings)
  "schedule.local.title": "இந்தக் கணினிக்கான அட்டவணைகள்",
  "schedule.local.hint": "இரவில் பூட்டுவது போல, குறிப்பிட்ட நேரத்தில் இந்தக் கணினியில் ஏதாவது செய்யுங்கள். my-domain திறந்திருக்கும்போது இயங்கும்; இந்தக் கணினி உறக்கத்தில் அல்லது அணைந்திருக்கும்போது தவறிய நேரம் தவிர்க்கப்படும்.",
