  // Automations (Settings): when something happens, do something
  "automation.title": "தன்னியக்கங்கள்",
  "automation.hint": "உங்கள் சாதனங்களில் ஒன்றில் ஏதாவது நடக்கும்போது, இங்கேயோ மற்றொரு சாதனத்திலோ ஏதாவது செய்யுங்கள். ஒவ்வொரு முறை இயங்கும்போதும் உங்களுக்கு ஒரு அறிவிப்பு வரும். இங்கே my-domain திறந்திருக்கும்போது செயல்படும்.",
