  // Verification codes from your phone (otp_codes.rs)
  "otp.toast": "{from} இலிருந்து குறியீடு {code}",
  "otp.toastCopied": "{from} இலிருந்து குறியீடு {code} · நகலெடுக்கப்பட்டது",
  "otp.copy": "நகலெடு",
  "otp.copied": "நகலெடுக்கப்பட்டது. 90 வினாடிகளில் கிளிப்போர்டிலிருந்து அழிக்கப்படும்.",
  "otp.expired": "அந்தக் குறியீடு காலாவதியாகிவிட்டது.",
  "otp.panelTitle": "சரிபார்ப்புக் குறியீடு",
  "otp.panelCopy": "{from} இலிருந்து வந்த குறியீடு {code} ஐ நகலெடு",
  "otp.left": "{n} வி மீதம்",
  "otp.autoCopy": "சரிபார்ப்புக் குறியீடுகளைத் தானாக நகலெடு",
  "otp.autoCopyHint": "உங்கள் ஃபோன் ஒருமுறைக் குறியீட்டை அனுப்பும்போது (ஃபோனின் அமைப்புகளில் அதை இயக்கவும்), அது நேரடியாக இந்தக் கிளிப்போர்டுக்கு வரும், கிளிப்போர்டு மேலாளர்கள் தவிர்க்கும்படி தனிப்பட்டதாகக் குறிக்கப்படும், 90 வினாடிகளுக்குப் பின் அழிக்கப்படும். அணைத்தால்: குறியீடு ‘நகலெடு’ பொத்தானுடன் காட்டப்படும். குறியீடுகள் எந்த வரலாற்றிலும் வைக்கப்படாது, 5 நிமிடங்களில் மறக்கப்படும்.",

  // Commands another computer lets you run (CommandsTile)
  "run.title": "கட்டளைகள்",
  "run.hint": "{name} இல், அங்குள்ள my-domain அமைப்புகளில் அமைக்கவும். ஒவ்வொரு முறை இயங்கும்போதும் அது ஒரு அறிவிப்பைக் காட்டும்.",
  "run.run": "இயக்கு",
  "run.running": "இயங்குகிறது…",
  "run.asked": "“{what}” ஐ இயக்க {name} இடம் கேட்டது",
  "run.queued": "{name} அணுகக்கூடியதாகும்போது இயங்கும்",
  "run.exitCode": "“{what}” வெளியேறும் குறியீடு {code} உடன் முடிந்தது",
  "run.timedOut": "“{what}” அதிக நேரம் எடுத்ததால் நிறுத்தப்பட்டது",
  "run.stopped": "“{what}” நிறுத்தப்பட்டது",
