  "run.noOutput": "வெளியீடு இல்லை.",

  // Commands this computer lets your devices run (Settings)
  "commands.title": "என் மற்ற சாதனங்கள் இயக்கக்கூடிய கட்டளைகள்",
  "commands.hint": "உங்கள் ஃபோனும் மற்ற கணினிகளும் இவற்றைப் பொத்தான்களாகக் காட்டி, இங்கு உங்கள் பெயரில் ஒரு நிமிடம் வரை இயக்கலாம். இங்கு எழுதிய கட்டளைகள் மட்டுமே இயங்கும், ஒவ்வொரு முறையும் உங்களுக்கு அறிவிப்பு வரும்.",
  "commands.empty": "இன்னும் எதுவும் இல்லை, அதனால் உங்கள் சாதனங்கள் இங்கு எதையும் இயக்க முடியாது.",
  "commands.name": "பெயர்",
  "commands.namePlaceholder": "பெயர், எ.கா. படங்களைக் காப்புப் பிரதி எடு",
  "commands.command": "கட்டளை",
  "commands.commandPlaceholder": "கட்டளை, எ.கா. rsync -a ~/Pictures /Volumes/Backup",
  "commands.add": "கட்டளையைச் சேர்",
  "commands.added": "“{name}” சேர்க்கப்பட்டது",
  "commands.edit": "திருத்து",
  "commands.save": "சேமி",
  "commands.cancel": "ரத்துசெய்",
  "commands.delete": "நீக்கு",
  "commands.test": "சோதி",
  "commands.testing": "இயங்குகிறது…",
