  // Webhooks (Settings): tools on this computer trigger actions
  "webhooks.title": "Webhooks",
  "webhooks.hint": "இந்தக் கணினியில் உள்ள Home Assistant, Shortcuts, ஒரு ஸ்கிரிப்ட் அல்லது Stream Deck போன்ற கருவிகள் my-domain பொத்தான்கள் செய்வதைச் செய்யட்டும்: ஒரு சாதனத்தை ஒலிக்கச் செய்தல், அதன் செயல்களில் ஒன்றை இயக்குதல், அதற்கு உரை அனுப்புதல் அல்லது ஒரு தானியக்கத்தை இயக்குதல். இந்தக் கணினி மட்டுமே, கீழே உள்ள டோக்கனுடன் மட்டுமே அதை அணுக முடியும், ஒவ்வொரு முறையும் உங்களுக்கு அறிவிப்பு வரும்.",
  "webhooks.switch": "இந்தக் கணினியில் உள்ள கருவிகள் webhooks ஐப் பயன்படுத்த அனுமதி",
  "webhooks.listening": "http://127.0.0.1:{port} இல் கேட்கிறது",
  "webhooks.notListening": "கேட்கவில்லை.",
  "webhooks.port": "போர்ட்",
  "webhooks.savePort": "போர்ட்டை மாற்று",
  "webhooks.portHint": "1024 முதல் 65535 வரையிலான எண். வேறு ஆப் {port} ஐப் பயன்படுத்தினால் மட்டும் மாற்றவும்.",
  "webhooks.portSaved": "இப்போது போர்ட் {port} இல்",
  "webhooks.token": "டோக்கன்",
  "webhooks.tokenHint": "கருவிகள் அதை Authorization: Bearer மற்றும் அதைத் தொடர்ந்து டோக்கன் என அனுப்பும். அது உள்ள எவரும் உங்கள் சாதனங்களைப் பயன்படுத்தலாம், எனவே அதை யாருடனும் பகிர வேண்டாம்.",
  "webhooks.show": "காட்டு",
