  "settings.batteryAlertsHint": "பேட்டரி உள்ள கணினியில் மட்டும். சார்ஜ் ஆகாதபோது {low}% குறைவு எனக் கருதப்படும். சார்ஜ் நிலை, நிரம்பியதும் சொல்வதற்குப் பதிலாக, ஒவ்வொரு சார்ஜுக்கும் ஒருமுறை சொல்லப்படும்.",
  "settings.shareLabels": "பெயர்களையும் ஐகான்களையும் என் மற்ற சாதனங்களுடன் பகிர்",
  "settings.shareLabelsHint": "இங்கே ஒரு சாதனத்துக்குக் கொடுக்கும் புனைப்பெயர், ஐகான் அல்லது நிறம் உங்கள் மற்ற சாதனங்களிலும் தெரியும், அங்கே அமைப்பவை இங்கே தெரியும். புதிய மாற்றமே செல்லும். அணைத்தால்: இந்தக் கணினி தன்னுடையதை வைத்துக்கொண்டு அவற்றைப் புறக்கணிக்கும்.",
