  "conn.verdict.punched": "இரு ரூட்டர்கள் வழியாகவும், இணையத்தில் நேரடியாக இணைக்கப்பட்டது",
  "conn.verdict.webrtc": "இணையம் வழியாக நேரடியாக இணைக்கப்பட்டது (WebRTC)",
  "conn.verdict.relay": "ரிலே சர்வர் வழியாகச் செல்கிறது — மெதுவானது; இரு சாதனங்களும் ஒரே Wi‑Fi இல் இருந்தால் இது சரியாகும்",
  "conn.verdict.ble": "Bluetooth வழியாக இணைக்கப்பட்டது — செய்திகளுக்குப் பரவாயில்லை, கோப்புகளுக்கு மெதுவானது",
