  "download.pickBody": "நீங்கள் தேர்ந்தெடுக்கும் சாதனம் அந்தக் கோப்பை இணையத்திலிருந்து நேரடியாகத் தன் பதிவிறக்கக் கோப்புறையில் பதிவிறக்கும்.",
  "download.link": "இணைப்பு",
  "download.notALink": "அது இணைய இணைப்பு அல்ல (http அல்லது https).",
  "download.noDevices": "உங்கள் சாதனங்கள் எதுவும் இன்னும் இணைப்புகளைப் பதிவிறக்க முடியாது. அவற்றில் my-domain ஐப் புதுப்பிக்கவும்.",
  "download.publicOnly": "பொது இணைப்புகள் மட்டும்: எதுவும் உள்நுழையாது, எனவே உள்நுழைவு தேவைப்படும் இணைப்பு தோல்வியடையலாம்.",
  "download.askTitle": "{device} இந்தக் கணினியிடம் ஒரு கோப்பைப் பதிவிறக்கக் கேட்கிறது",
  "download.sizeUnknown": "அளவு தெரியவில்லை",
  "download.askFrom": "{host} இலிருந்து",
  "download.askNote": "இது உங்கள் பதிவிறக்கக் கோப்புறையில் சேமிக்கப்படும், தானாக ஒருபோதும் திறக்கப்படாது.",
  "download.allow": "அனுமதி",
  "download.alwaysAllow": "{device} ஐ எப்போதும் அனுமதி",
  "download.dontAllow": "அனுமதிக்காதே",
  "download.sendToHint": "இது சேமித்த இணைய இணைப்பு. அதற்குப் பதிலாக ஒரு சாதனம் கோப்பைத் தானே பதிவிறக்கலாம்:",
  "download.onDevice": "கோப்பை {device} இல் பதிவிறக்கு",
  "download.settingsTitle": "என் சாதனங்களிலிருந்து பதிவிறக்கங்கள்",
  "download.settingsIntro": "உங்கள் மற்றொரு சாதனம் ஒரு இணைப்பைப் பதிவிறக்க இந்தக் கணினியிடம் கேட்கலாம் (அங்கே ‘இதில் பதிவிறக்கு…’). கோப்பு உங்கள் பதிவிறக்கக் கோப்புறைக்குச் செல்லும், தானாக ஒருபோதும் திறக்கப்படாது.",
  "download.policy": "ஒரு சாதனம் கேட்கும்போது",
