  "download.allowLan": "உள்ளூர் நெட்வொர்க்குக்கான இணைப்புகளை அனுமதி",
  "download.allowLanHint": "அணைத்தால்: இந்தக் கணினி, உங்கள் ரூட்டர் அல்லது வீட்டிலுள்ள மற்ற சாதனங்களுக்கான இணைப்புகள் (192.168…, .local பெயர்கள்) மறுக்கப்படும்.",
