  "download.settingsNote": "பொது இணைப்புகள் மட்டுமே வேலை செய்யும்: உள்நுழைவு, குக்கீகள், கடவுச்சொற்கள் எதுவும் பயன்படுத்தப்படாது.",
  "palette.readLink": "பின்னர் படி: {title}",
