  "search.subtitle": "செய்திகள், குறிப்புகள், கிளிப்போர்டு, அறிவிப்புகள், கோப்புகள், ஒத்திசைக்கப்பட்ட கோப்புறைகள், சாதனங்கள், தானியக்கங்கள், உதவி, அமைப்புகள். இந்தக் கணினியில் உள்ளவை மட்டுமே தேடப்படும்; எதுவும் எங்கும் அனுப்பப்படாது.",
