  "panel.close": "மூடு (Esc)",
  "settings.quickPanel": "மெனு-பார் ஐகானைக் கிளிக் செய்யும்போது விரைவுப் பலகத்தைத் திற",
  "settings.quickPanelHint": "my-domain ஐகானைக் கிளிக் செய்தால் உங்கள் சாதனங்கள், சமீபத்திய கிளிப்புகள், கோப்புகள், தேடல் ஆகியவை உள்ள ஒரு சிறிய பலகம் திறக்கும். மெனுவுக்கு வலது கிளிக் செய்யவும். முடக்கத்தில்: கிளிக் செய்தால் மெனு தோன்றும். Linux-இல் எப்போதும் மெனுவே தோன்றும்; அதில் “விரைவுப் பலகம்” என்பதைத் தேர்ந்தெடுக்கவும்.",
  "settings.wifiDirect": "அருகில் இருக்கும்போது பெரிய கோப்புகளுக்கு Wi-Fi Direct-ஐப் பயன்படுத்து",
  "settings.wifiDirectHint": "இந்தக் கணினிக்கு அருகிலுள்ள ஃபோனுக்கு அல்லது அதிலிருந்து 20 MB-க்கு மேற்பட்ட கோப்பு, இரண்டும் ஒரே நெட்வொர்க்கில் இல்லாதபோது Wi-Fi Direct வழியாகச் செல்லும். முதல் முறை ஃபோன் அனுமதி கேட்கலாம்.",
  "settings.phoneHotspot": "பெரிய கோப்புகளுக்கு ஃபோனின் ஹாட்ஸ்பாட்டைப் பயன்படுத்து",
  "settings.phoneHotspot.ask": "ஒவ்வொரு முறையும் கேள்",
  "settings.phoneHotspot.always": "எப்போதும்",
