  "settings.phoneHotspotHint": "இந்தக் கணினியின் நெட்வொர்க்கில் இல்லாத (அல்லது நெட்வொர்க்கே இல்லாத) ஃபோனுடன் 20 MB-க்கு மேற்பட்ட கோப்பு, ஃபோனின் சொந்த ஹாட்ஸ்பாட் வழியாகச் செல்லலாம். முடியும் வரை இந்தக் கணினி தன் Wi-Fi-ஐ விட்டு விலகி, பின்னர் திரும்பும்.",
