  "print.title": "உங்கள் ஃபோனிலிருந்து அச்சிடுங்கள்",
  "print.loading": "பிரிண்டர்களைத் தேடுகிறது…",
  "print.unsupported": "ஃபோனிலிருந்து அச்சிட CUPS தேவை, அது macOS-இலும் Linux-இலும் உள்ளது. Windows-இல் ஒரு PDF-ஐத் தானாக அச்சிட உள்ளமைந்த வழி இல்லை, எனவே இந்தக் கணினி உங்கள் ஃபோனுக்கு அச்சிடும் வசதியை வழங்காது.",
