  "print.allowHint": "இந்தக் கணினியும் அதன் பிரிண்டர்களும் உங்கள் ஃபோனின் அச்சு உரையாடலில் தோன்றும் (எந்த ஆப்பிலும்: அச்சிடு → my-domain). ஆவணம் PDF ஆக இங்கு வந்து, அச்சிடப்பட்டு, நீக்கப்படும்.",
  "print.ask": "அச்சிடும் முன் கேள்",
  "print.askHint": "நீங்கள் “இங்கே அச்சிடு” என்று சொல்லும் வரை ஒவ்வொரு வேலையும் காத்திருக்கும். இரண்டு நிமிடங்களில் பதில் இல்லையென்றால் அச்சிடப்படாது.",
  "print.printers": "உங்கள் ஃபோன் காணும் பிரிண்டர்கள்",
  "print.none": "பிரிண்டர்கள் எதுவும் கிடைக்கவில்லை. உங்கள் கணினியின் பிரிண்டர் அமைப்புகளில் ஒன்றைச் சேர்க்கவும்.",
  "print.default": "இயல்பு",
