  "print.yes": "அச்சிடு",
  "print.no": "அச்சிட வேண்டாம்",
  "trayBattery.switch": "என் ஃபோனின் பேட்டரியை மெனு பாரில் காட்டு",
  "trayBattery.hint": "Mac-இலும் Linux-இலும் my-domain ஐகானுக்கு அருகில் (சார்ஜ் ஆகும்போது ⚡); Windows-இல் ஐகானின் உதவிக்குறிப்பில். ஃபோன் அரை மணிநேரம் துண்டிக்கப்பட்டிருந்தால் அது மறைந்துவிடும்.",
  "trayBattery.phone": "ஃபோன்",
  "trayBattery.anyPhone": "கடைசியாகத் தொடர்புகொண்டது",
  "trayBattery.noPhone": "இன்னும் ஃபோன் இல்லை: my-domain உள்ள உங்கள் Android ஃபோன் இணைந்ததும் தோன்றும்.",
  "trayBattery.badge": "பேட்டரி குறைவாக இருக்கும்போது ஐகானில் சிவப்புப் புள்ளி வை",
  "trayBattery.badgeHint": "20% அல்லது அதற்குக் குறைவாக, சார்ஜ் ஆகாதபோது.",

  // Wake a sleeping computer (Wake-on-LAN)
  "wake.button": "எழுப்பு",
  "wake.waking": "எழுப்புகிறது…",
  "wake.hint": "இது உறக்கத்தில் இருப்பது போலத் தெரிகிறது. “எழுப்பு” உங்கள் வீட்டு நெட்வொர்க் வழியாக ஓர் எழுப்பும் சிக்னலை அனுப்பும்; விழித்ததும் மீண்டும் இணையும்.",
  "wake.sent": "இந்த நெட்வொர்க்கில் எழுப்பும் சிக்னல் அனுப்பப்பட்டது.",
  "wake.sentRelayed": "எழுப்பும் சிக்னல் அனுப்பப்பட்டது, {names} வழியாகவும்.",
  "wake.awake": "{name} விழித்துவிட்டது.",
  "wake.noAnswer": "{name} விழிக்கவில்லை. அது இந்த நெட்வொர்க்கில் இருக்க வேண்டும், நெட்வொர்க் அணுகலுக்கு விழிக்கும்படி அமைக்கப்பட்டிருக்க வேண்டும்.",
  "wake.title": "இந்தக் கணினியை எழுப்பு",
  "wake.switch": "என் மற்ற சாதனங்கள் இந்தக் கணினியை எழுப்ப அனுமதி",
  "wake.switchHint": "உங்கள் ஃபோனும் மற்ற கணினிகளும் இந்தக் கணினியின் நெட்வொர்க் முகவரியை அறிந்துகொள்ளும், எனவே “எழுப்பு” மூலம் உறக்கத்திலிருந்து எழுப்ப முடியும். உங்கள் சொந்தச் சாதனங்கள் மட்டும், உங்கள் வீட்டு நெட்வொர்க்கில் மட்டும்.",
  "wake.hintMac": "Mac-உம் விழிக்கும்படி அமைக்கப்பட வேண்டும்: சிஸ்டம் அமைப்புகள் → பேட்டரி (அல்லது ஆற்றல் சேமிப்பு) → விருப்பங்கள் → நெட்வொர்க் அணுகலுக்கு விழி.",
  "wake.hintWindows": "PC-யும் விழிக்கும்படி அமைக்கப்பட வேண்டும்: சாதன மேலாளர் → உங்கள் நெட்வொர்க் அடாப்டர் → பண்புகள் → ஆற்றல் மேலாண்மை → இந்தச் சாதனம் கணினியை எழுப்ப அனுமதி. பல PC-களில் BIOS/UEFI-இல் Wake on LAN-ஐயும் இயக்க வேண்டும்.",
  "wake.hintLinux": "கணினியும் விழிக்கும்படி அமைக்கப்பட வேண்டும்: sudo ethtool -s <card> wol g ஐ இயக்கி, BIOS/UEFI-இல் Wake on LAN-ஐ இயக்கவும்.",
  "wake.wompOn": "நெட்வொர்க் அணுகலுக்கு விழித்தல் இயக்கத்தில் உள்ளது.",
  "wake.wompOff": "நெட்வொர்க் அணுகலுக்கு விழித்தல் முடக்கத்தில் உள்ளது: சிஸ்டம் அமைப்புகளில் அதை இயக்கவும், இல்லையெனில் இந்த Mac விழிக்காது.",
  "wake.cards": "பகிரப்பட்டவை: {cards}",
  "wake.wired": "{iface} (வயர்டு)",
  "wake.wifi": "{iface} (Wi-Fi)",
  "wake.noCards": "இப்போது வயர்டு அல்லது Wi-Fi இணைப்பு எதுவும் இயக்கத்தில் இல்லை.",
  "wake.wifiOnly": "Wi-Fi மட்டுமே இணைக்கப்பட்டுள்ளது. Wi-Fi வழியாக எழுப்பக்கூடிய கணினிகள் குறைவு; நெட்வொர்க் கேபிள் மிகச் சிறப்பாக வேலை செய்யும்.",
  "backup.title": "அமைப்புகளைக் காப்புப் பிரதி எடுத்து மீட்டெடு",
  "backup.hint": "இந்த ஆப்பின் அமைப்புகளை ஒரு கோப்பில் சேமித்து, மீண்டும் நிறுவிய பிறகு அல்லது புதிய கணினியில் மீட்டெடுக்கவும்: விருப்பத்தேர்வுகள், தானியக்கங்கள், அட்டவணைகள், கட்டளைகள், குறுக்குவழிகள், webhook அமைப்புகள், சாதனப் பெயர்கள், பக்க அமைப்புகள், ஒத்திசைக்கப்பட்ட கோப்புறைகள், தீம், மொழி.",
  "backup.never": "கோப்பில் ஒருபோதும் இருக்காதவை: உங்கள் கடவுச்சொல், சாதன விசை, உள்நுழைவு, webhook டோக்கன், அல்லது எந்தச் செய்தி, அறிவிப்பு, கிளிப்போர்டு, குறிப்பும்.",
  "backup.save": "அமைப்புகளைக் காப்புப் பிரதி எடு…",
  "backup.restore": "அமைப்புகளை மீட்டெடு…",
  "backup.saved": "அமைப்புகள் காப்புப் பிரதி எடுக்கப்பட்டன",
  "backup.previewTitle": "இந்த அமைப்புகளை மீட்டெடுக்கவா?",
  "backup.from": "{platform}-இல் காப்புப் பிரதி எடுக்கப்பட்டது, {when}. எதை மீட்டெடுக்க வேண்டுமோ அதை டிக் செய்யவும்.",
