  "setup.name.hint": "உங்கள் மற்ற சாதனங்கள் இந்தக் கணினியை இந்தப் பெயரில் பட்டியலிடும்.",
  "setup.name.label": "பெயர்",
  "setup.devices.hint": "இந்தக் குறியீட்டை உங்கள் ஃபோனுக்கோ மற்ற கணினிக்கோ காட்டுங்கள் (ஸ்கேன் செய்யுங்கள், அல்லது அங்கே 6 இலக்கக் குறியீட்டைத் தட்டச்சு செய்யுங்கள்). ஏற்கனவே சேர்த்துவிட்டீர்களா? தொடருங்கள்.",
