  "setup.devices.none": "இன்னும் வேறு சாதனங்கள் இல்லை.",
  "setup.features.hint": "உங்களுக்கு வேண்டியதைத் தேர்ந்தெடுங்கள். இவற்றில் எதையும் பின்னர் அமைப்புகளில் மாற்றலாம்.",
